\begin{thm}[Arithmetical induction]\ollabel{thm:dedinfiniteinduction}
Let $N, s, o$ comprise a Dedekind algebra. Then for any set $X$:  
	\begin{center}
		if $o \in X$ and $(\forall {n} \in N \cap X){s}({n}) \in X$, {then} $N \subseteq X$.
	\end{center}
\end{thm}

target_text:
\Needspace{6\baselineskip}\begin{thm}[Récurrence arithmétique]\ollabel{thm:dedinfiniteinduction}
Soit $N,s,o$ une algèbre de Dedekind. Pour tout ensemble $X$ :
	\begin{center}
		si $o \in X$ et $(\forall {n} \in N \cap X){s}({n}) \in X$,
		alors $N \subseteq X$.
	\end{center}
\end{thm}

source_text:
\begin{proof}
By the definition of a Dedekind algebra, $N = \closureofunder{s}{o}$.
Now if both ${o} \in X$ and $(\forall {n} \in N)(n \in X \lif
{s}({n}) \in X)$, then $N = \closureofunder{s}{o} \subseteq X$.
\end{proof}

\begin{cor}\ollabel{natinductionschema}
Let $N, s, o$ comprise a Dedekind algebra. Then for any formula
$\phi(x)$, which may have parameters:
\begin{center}
	if $\phi(o)$ and $(\forall {n} \in N)(\phi(n)\lif
	\phi({s}({n})))$, {then} $(\forall n \in N)\phi(n)$
\end{center}
\end{cor}

target_text:
\begin{cor}\ollabel{natinductionschema}
Soit $N,s,o$ une algèbre de Dedekind. Pour toute formule $\phi(x)$,
éventuellement avec des paramètres :
\begin{center}
	si $\phi(o)$ et $(\forall {n} \in N)(\phi(n)\lif
	\phi({s}({n})))$, alors $(\forall n \in N)\phi(n)$.
\end{center}
\end{cor}

